  const bytes=Buffer.from(member.base64,'base64');
  need(bytes.toString('base64')===member.base64&&bytes.length===member.bytes&&sha(bytes)===member.sha256,
    'GRANTS_CAPTURE_EXPORT_DIGEST_MISMATCH');
